        bleedDurationFromCriticalBonus = SaturatedArithmetic.saturatingAdd(bleedDurationFromCriticalBonus, other.bleedDurationFromCriticalBonus)
        bleedDurationVsPoisonedBonus = SaturatedArithmetic.saturatingAdd(bleedDurationVsPoisonedBonus, other.bleedDurationVsPoisonedBonus)
        burnAttackBleedChancePercent += other.burnAttackBleedChancePercent
        burnAttackBleedDamage = SaturatedArithmetic.saturatingAdd(burnAttackBleedDamage, other.burnAttackBleedDamage)
        poisonPreventDecayChancePercent += other.poisonPreventDecayChancePercent
        poisonDamageVsStunnedMultiplier *= other.poisonDamageVsStunnedMultiplier
        bleedDamageBelowHalfMultiplier *= other.bleedDamageBelowHalfMultiplier
        onDamageBurnRetaliationChancePercent += other.onDamageBurnRetaliationChancePercent
        onDamageBurnRetaliationDamage = SaturatedArithmetic.saturatingAdd(onDamageBurnRetaliationDamage, other.onDamageBurnRetaliationDamage)
        burnPreventDecayChancePercent += other.burnPreventDecayChancePercent
        bleedPoisonOncePerTurn = bleedPoisonOncePerTurn || other.bleedPoisonOncePerTurn
        enemyPoisonDecaySlowPercent = max(enemyPoisonDecaySlowPercent, other.enemyPoisonDecaySlowPercent)
        enemyPoisonPreventDecayChancePercent = max(enemyPoisonPreventDecayChancePercent, other.enemyPoisonPreventDecayChancePercent)
        enemyPoisonDecayIncreaseChance = max(enemyPoisonDecayIncreaseChance, other.enemyPoisonDecayIncreaseChance)
        enemyBurnDecaySlowPercent = max(enemyBurnDecaySlowPercent, other.enemyBurnDecaySlowPercent)
        enemyBurnDecaySlowVsBleedingPercent = max(enemyBurnDecaySlowVsBleedingPercent, other.enemyBurnDecaySlowVsBleedingPercent)
        enemyBurnPreventDecayChancePercent = max(enemyBurnPreventDecayChancePercent, other.enemyBurnPreventDecayChancePercent)
    }
}

extension DotTriggers {
    /// Decodes this family's flat trigger keys.
    init(from values: DefaultingTriggerDecoder) throws {
        self.init()
        for field in Self.schema {
            try field.decode(values, &self)
        }
    }

    func encode(to container: inout KeyedEncodingContainer<TriggerCodingKey>) throws {
        for field in Self.schema {
            try field.encode(self, &container)
        }
    }
}
